($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 14020038, $f$Two Fantasy Idiots Talk to Each Other$f$, ARRAY[$f$Libelli$f$]::text[], ARRAY[$f$Kingkiller Chronicles - Patrick Rothfuss$f$, $f$Gentleman Bastard Sequence - Scott Lynch$f$]::text[], NULL, ARRAY[]::text[], $f$Locke Lamora and Kvothe. Different universes. Different stories. Different careers. But are the two characters themselves that different?$f$, 1031, 4, NULL, false, -1, false, $f$2018-12-28T18:11:20.045+00:00$f$, $f$2018-12-28T18:11:20.111+00:00$f$, $f$2018-07-18T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 14032170, $f$don't worry (i'm the outsider)$f$, ARRAY[$f$krizzle$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$The Outsider was first and foremost an observer. Then Corvo Attano happened.$f$, 272, 1, 1, true, -1, false, $f$2019-05-01T11:38:16.197+00:00$f$, $f$2019-05-01T11:38:16.227+00:00$f$, $f$2018-03-20T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 14036889, $f$The Spring Equinox$f$, ARRAY[$f$bluebeholder$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$, $f$Fantastic Beasts and Where to Find Them (Movies)$f$]::text[], NULL, ARRAY[]::text[], $f$More than one lord among the fair folk has a mortal lover. It's Corvo's first time attending a revel like this, and of course he's there on the Equinox. It's going to be a wild night.$f$, 1658, 1, 2, false, -1, false, $f$2019-05-01T11:38:10.018+00:00$f$, $f$2019-05-01T11:38:10.059+00:00$f$, $f$2018-03-20T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 14055147, $f$Все или ничего$f$, ARRAY[$f$Gianeya$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], NULL, NULL, 2, 2, true, -1, false, $f$2018-08-25T13:23:46.564+00:00$f$, $f$2018-08-25T13:23:46.695+00:00$f$, $f$2018-03-22T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
