($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 14578941, $f$a river to the sea$f$, ARRAY[$f$thescrewtapedemos$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$The room shakes for a moment. It had struck the wall. Corvo grits his teeth against the frustration. 
Come and get me, you bastard, he thinks viciously. He's not ready, never was ready to die but he doesn't want to wait for it, doesn't want to linger in this closet that reeks of mildew.$f$, 12642, 1, 1, true, -1, false, $f$2019-05-01T11:33:34.961+00:00$f$, $f$2019-05-01T11:33:35.064+00:00$f$, $f$2018-05-08T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 14593056, $f$Holy Hands oh They Make Me a Sinner$f$, ARRAY[$f$capeswithhoods$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$Corvo is dreaming, until he’s not and the Void is pulling him in and materialising around him, dragging him from nightmares he can’t stop having. He’s grateful for the intrusion and he thinks the Outsider might have done this on purpose.$f$, 2416, 1, 1, true, 1, false, $f$2019-05-02T12:14:28.872+00:00$f$, $f$2019-05-02T12:14:28.943+00:00$f$, $f$2018-05-09T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
