($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 15126476, $f$dead flowers$f$, ARRAY[$f$havisham$f$, $f$Sath$f$]::text[], ARRAY[$f$ジョジョの奇妙な冒険 | JoJo no Kimyou na Bouken | JoJo's Bizarre Adventure$f$]::text[], NULL, ARRAY[]::text[], $f$Send me dead flowers to my wedding / And I won't forget to put roses on your grave Giorno, like his father before him, always gets what he wants.$f$, 2338, 1, 1, true, 5, false, $f$2019-06-08T03:24:06.842+00:00$f$, $f$2019-06-08T03:24:07.147+00:00$f$, $f$2018-07-01T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
